 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";
import type { Issue, IssueBoardColumn, IssueWithRelations } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

export async function updateIssue(
  actor: Actor,
  input: UpdateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.updateIssue(input);

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: Object.keys(input).filter(
      (key) => key !== "orgId" && key !== "issueId",
    ),
  });

  return after;
}

/** Status transitions are an `issue:update`, not a separate permission. */
export async function changeIssueStatus(
  actor: Actor,
  input: ChangeIssueStatusInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.status === input.status) return before;

  const after = await issueRepo.setIssueStatus(
    input.orgId,
    input.issueId,
    input.status,
  );

  await emit("issue.status_changed", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    from: before.status,
    to: after.status,
  });

  return after;
}

/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Un-assigning publishes `issue.updated` instead, since
 * `issue.assigned` carries a non-null assignee by contract.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    input.assigneeId,
  );

  if (input.assigneeId === null) {
    await emit("issue.updated", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      changedFields: ["assigneeId"],
    });
    return after;
  }

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId: input.assigneeId,
  });

  return after;
}

export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const archived = await issueRepo.archiveIssue(orgId, issueId);

  await emit("issue.archived", {
    ...actorEnvelope(actor),
    issueId: archived.id,
    projectId: archived.projectId,
  });

  return archived;
}

/**
 * Board drag-and-drop. The index is presentation-only — the board renders by
 * `updated_at` — so a move is a status change plus a touch.
 */
export async function moveIssue(
  actor: Actor,
  input: MoveIssueInput,
): Promise<Issue> {
  return changeIssueStatus(actor, {
    orgId: input.orgId,
    issueId: input.issueId,
    status: input.toStatus,
  });
}

export async function getIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueWithRelations> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);

  return {
    issue,
    labels: labels[issue.id] ?? [],
    commentCount: await commentRepo.countComments(orgId, issue.id),
    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))
      .length,
  };
}

export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(input);
}

export async function getBoard(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueBoardColumn[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "issue:read", projectResource(project));

  return issueRepo.listBoardColumns(orgId, projectId);
}
import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

/**
 * Soft-delete conventions.
 *
 * Issues, projects and comments are never physically removed — they get an
 * `archived_at` timestamp. Repositories must express "live rows only" through
 * these helpers so the predicate stays in one place; a raw
 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
 * drift this module prevents.
 */

export function isArchived(row: SoftDeletable): boolean {
  return row.archivedAt !== null;
}

export function isLive(row: SoftDeletable): boolean {
  return row.archivedAt === null;
}

/** Filters an in-memory collection according to an `ArchiveScope`. */
export function applyArchiveScope<T extends SoftDeletable>(
  rows: readonly T[],
  scope: ArchiveScope = {},
): readonly T[] {
  return scope.includeArchived === true ? rows : rows.filter(isLive);
}

/** True when the repository should add the `archived_at IS NULL` predicate. */
export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
  return scope.includeArchived !== true;
}

/** The column patch that archives a row. */
export function archivePatch(now: Date = new Date()): {
  archivedAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
} {
  const stamp = toIsoTimestamp(now);
  return { archivedAt: stamp, updatedAt: stamp };
}

/** The column patch that restores an archived row. */
export function restorePatch(now: Date = new Date()): {
  archivedAt: null;
  updatedAt: IsoTimestamp;
} {
  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
}

export class AlreadyArchivedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly entity: string, readonly id: string) {
    super(`${entity} ${id} is already archived.`);
    this.name = "AlreadyArchivedError";
  }
}

/** Guard for archive actions, so double-archiving is a domain-level conflict. */
export function assertNotArchived(
  entity: string,
  id: string,
  row: SoftDeletable,
): void {
  if (isArchived(row)) {
    throw new AlreadyArchivedError(entity, id);
  }
}
/**
 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
 *
 * Must call (do not reimplement): getPlanLimits, isArchived
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

const ORG_BATCH = 25;
const PAGE_SIZE = 100;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. Soft-deleted rows are kept for as long as the plan
 * promises and no longer: the cut-off comes from `retentionDays`, so an
 * enterprise tenant keeps years of history where a free one keeps a month.
 *
 * Only the search documents are actually dropped here — the issue rows stay,
 * because the audit log still points at them — while the audit rows past the
 * window are purged outright.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = toIsoTimestamp(
        new Date(now.getTime() - retentionDays * MS_PER_DAY),
      );

      const archived = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: null,
        includeArchived: true,
      });

      for (const issue of archived.items) {
        if (!isArchived(issue)) continue;
        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;

        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
        result.processed += 1;
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
import type { LimitedResource, PlanId } from "@/types/billing";
import type { FeatureFlagKey } from "@/types/feature-flag";

/**
 * The one place plan quotas are declared.
 *
 * `BillingService`, the invite flow, the project-create action, the webhook
 * settings page, the usage meter component and the seat-limit job all read
 * their numbers from here via `getPlanLimits()`. Adding a field to
 * `PlanLimits` therefore ripples into every one of those call sites — that
 * ripple is intentional and is what keeps the quotas honest.
 */
export interface PlanLimits {
  readonly plan: PlanId;
  readonly seats: number;
  readonly projects: number;
  readonly issuesPerProject: number;
  readonly storageMb: number;
  readonly apiRequestsPerHour: number;
  readonly webhooks: number;
  readonly retentionDays: number;
  readonly includedFlags: readonly FeatureFlagKey[];
  readonly priceCentsPerSeatMonthly: number;
}

/** `Infinity` is the sanctioned representation of "no limit". */
export const UNLIMITED = Number.POSITIVE_INFINITY;

export const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {
  free: {
    plan: "free",
    seats: 3,
    projects: 2,
    issuesPerProject: 100,
    storageMb: 100,
    apiRequestsPerHour: 100,
    webhooks: 0,
    retentionDays: 30,
    includedFlags: ["command_palette"],
    priceCentsPerSeatMonthly: 0,
  },
  starter: {
    plan: "starter",
    seats: 10,
    projects: 10,
    issuesPerProject: 1_000,
    storageMb: 2_000,
    apiRequestsPerHour: 1_000,
    webhooks: 2,
    retentionDays: 90,
    includedFlags: ["command_palette", "kanban_board", "csv_export"],
    priceCentsPerSeatMonthly: 900,
  },
  growth: {
    plan: "growth",
    seats: 50,
    projects: 100,
    issuesPerProject: 10_000,
    storageMb: 20_000,
    apiRequestsPerHour: 10_000,
    webhooks: 10,
    retentionDays: 365,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
    ],
    priceCentsPerSeatMonthly: 1_900,
  },
  enterprise: {
    plan: "enterprise",
    seats: UNLIMITED,
    projects: UNLIMITED,
    issuesPerProject: UNLIMITED,
    storageMb: 500_000,
    apiRequestsPerHour: 100_000,
    webhooks: UNLIMITED,
    retentionDays: 2_555,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
      "advanced_search",
      "public_projects",
      "ai_issue_summary",
    ],
    priceCentsPerSeatMonthly: 3_900,
  },
};

/** Plans ordered cheapest → richest; used for "at least this plan" checks. */
export const PLAN_ORDER: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export function getPlanLimits(plan: PlanId): PlanLimits {
  return PLAN_LIMITS[plan];
}

/** Reads one numeric quota without the caller destructuring `PlanLimits`. */
export function getLimit(plan: PlanId, resource: LimitedResource): number {
  return getPlanLimits(plan)[resource];
}

/** True when `plan` is at least as rich as `minPlan`. */
export function planAtLeast(plan: PlanId, minPlan: PlanId): boolean {
  return PLAN_ORDER.indexOf(plan) >= PLAN_ORDER.indexOf(minPlan);
}

/** True when consuming `requested` more units would breach the quota. */
export function wouldExceedLimit(
  plan: PlanId,
  resource: LimitedResource,
  used: number,
  requested = 1,
): boolean {
  return used + requested > getLimit(plan, resource);
}

