const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * True once an archived row has sat in the trash for `retentionDays` or
 * longer. Expired rows can no longer be restored and are purged by the
 * retention sweep; live rows never expire.
 */
export function isExpired(
  row: SoftDeletable,
  retentionDays: number,
  now: Date = new Date(),
): boolean {
  if (row.archivedAt === null) return false;
  const archivedAt = Date.parse(row.archivedAt);
  return now.getTime() - archivedAt >= retentionDays * MS_PER_DAY;
}

export type RestoreRefusalReason =
  | "not_archived"
  | "expired"
  | "project_archived"
  | "quota";

const REFUSAL_MESSAGES: Readonly<Record<RestoreRefusalReason, string>> = {
  not_archived: "is not archived",
  expired: "has been archived for longer than the plan's retention period",
  project_archived: "belongs to an archived project",
  quota: "does not fit under the plan's per-project issue quota",
};

/** A restore the domain rules forbid; nothing is changed when it is thrown. */
export class RestoreRefusedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: RestoreRefusalReason,
    readonly entity: string = "Issue",
    readonly id: string = "",
  ) {
    super(
      `${entity}${id === "" ? "" : ` ${id}`} cannot be restored: it ${REFUSAL_MESSAGES[reason]}.`,
    );
    this.name = "RestoreRefusedError";
  }
}
