/** Every archived issue of the tenant, across all projects, unpaged. */
export async function listArchivedIssues(
  orgId: OrgId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), isNotNull(issues.archivedAt)))
    .orderBy(issues.archivedAt, issues.id)
    .all();

  return rows.map((row) => toIssue(row));
}

/** What a purge removed, so callers can clean up the index and the quota. */
export interface PurgedIssue {
  readonly issueId: IssueId;
  readonly projectId: ProjectId;
  readonly commentIds: readonly CommentId[];
  readonly attachmentSizes: readonly number[];
}

/**
 * Hard delete for the retention sweep: the issue row goes, together with its
 * label links, comments and attachments. The issue's number is recorded as
 * used first so a purge can never free it for reuse. Returns `null` when the
 * issue does not exist.
 */
export async function purgeIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<PurgedIssue | null> {
  const db = getDb();

  return db.transaction((tx) => {
    const issue = tx
      .select({ projectId: issues.projectId, number: issues.number })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!issue) return null;

    tx.insert(issueNumberSequences)
      .values({ orgId, projectId: issue.projectId, lastNumber: issue.number })
      .onConflictDoUpdate({
        target: issueNumberSequences.projectId,
        set: {
          lastNumber: sql`max(${issueNumberSequences.lastNumber}, ${issue.number})`,
        },
      })
      .run();

    const commentRows = tx
      .delete(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
      )
      .returning({ id: comments.id })
      .all();

    const attachmentRows = tx
      .delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .returning({ sizeBytes: attachments.sizeBytes })
      .all();

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.issueId, issueId),
        ),
      )
      .run();

    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .run();

    return {
      issueId,
      projectId: issue.projectId as ProjectId,
      commentIds: commentRows.map((row) => row.id as CommentId),
      attachmentSizes: attachmentRows.map((row) => row.sizeBytes),
    };
  });
}
'''
open(p,'w').write(s)
EOF
